                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 验签过程发生内部错误"}
                )
                return
            if not ok:
                self._send_json(
                    200, {"results": [], "reason": reason or "请求不合法"}
                )
                return
            self._send_json(200, {"results": results})

        def _post_trust_credentials_verify_batch_with_status(
            self, tenant: str
        ) -> None:
            # 批量外部凭证验真并合并本租户同步状态：与 verify-batch 相同的
            # 公开错误协议，任何失败都返回 HTTP 200。请求体须恰为
            # {"credentials": [项...]}，数组非空且不超过 100 项；请求体非法
            # （含非法 JSON、空数组、超过上限）时返回
            # {"results": [], "reason": "请求..."}。请求级合法时逐项复用
            # verify-with-status 规则（验真 + 只读合并同步状态），按输入
            # 顺序返回 {"results": [...]}，失败不短路。只读，不写凭证、
            # 状态、同步记录、历史或审计。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_json(
                    200,
                    {"results": [],
                     "reason": "请求不合法: 请求体缺失或长度声明非法"},
                )
                return
            except Exception:  # noqa: BLE001
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
                )
                return
            if not raw:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体缺失"}
                )
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_json(
                    200,
                    {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
                )
                return
            except json.JSONDecodeError:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
                )
                return

            try:
                ok, reason, results = (
                    store.verify_trust_credentials_batch_with_status(
                        tenant, data
                    )
                )
            except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 验签过程发生内部错误"}
                )
                return
            if not ok:
                self._send_json(
                    200, {"results": [], "reason": reason or "请求不合法"}
                )
                return
            self._send_json(200, {"results": results})

        def _post_trust_credentials_verify_with_status(
            self, tenant: str
        ) -> None:
            # 外部凭证验真并合并状态判定：公开错误协议，任何失败都返回
            # 200 + {"valid": false, "reason": "<非空中文原因>"}。
            # 请求体须恰含 body（对象）与 signature（非空字符串），解析
            # 规则与 /v1/trust/credentials/verify 完全一致；验真通过后
            # 由 store 只读查询本租户同步状态。纯只读，不写状态、不记审计。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_invalid("请求体缺失或长度声明非法")
                return
            except Exception:  # noqa: BLE001
                self._send_invalid("请求体读取失败")
                return
            if not raw:
                self._send_invalid("请求体缺失")
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_invalid("请求体不是合法 UTF-8 文本")
                return
            except json.JSONDecodeError:
                self._send_invalid("请求体不是合法 JSON")
                return

            try:
                valid, reason = (
                    store.verify_trust_credential_with_status(tenant, data)
                )
            except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
                self._send_invalid("验签过程发生内部错误")
                return
            payload: Dict[str, Any] = {"valid": valid}
            if not valid:
                payload["reason"] = reason or "验签失败"
            self._send_json(200, payload)

        def _post_trust_credential_status_sync(self, tenant: str) -> None:
            # 外部凭证状态同步。请求/字段非法由 _read_json 与 store 抛
            # ValidationError -> 400；同 updated_at 不同内容由 store 抛
            # ConflictError -> 409。锚点缺失/吊销、签名格式错误、验签
            # 失败均按公开错误协议返回 200 + {"valid":false,"reason":...}
            # （前缀依次为“锚点”/“签名格式错误”/“签名校验失败”）且不写入。
            data = self._read_json()
            result = store.sync_credential_status(tenant, data)
            if not result.get("valid"):
                self._send_invalid(result.get("reason") or "验签失败")
                return
            record = result["record"]
            # 首次同步 201；严格更新或重放 200（重放内容不变）。
            self._send_json(
                result["status_code"],
                {
                    "issuer_did": record.issuer_did,
                    "credential_id": record.credential_id,
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                    "issuer_key_version": record.issuer_key_version,
                },
            )

        def _post_trust_credential_status_sync_batch(
            self, tenant: str
        ) -> None:
            # 批量外部凭证状态同步：任何失败都返回 HTTP 200。请求体须恰为
            # {"items": [项...]}，数组非空且不超过 100 项；请求体非法
            # （外层缺失、非法 JSON、非对象、字段缺失或多余、items 非数组、
            # 空数组或超过上限）时返回 {"results": [], "reason": "请求..."}。
            # 请求级合法时返回 {"results": [...]}，长度与顺序与输入一致，
            # 逐项复用单项同步规则，失败不短路：字段错误 400、同秒冲突
            # 409、锚点/签名失败 200 均收敛为单项结果（含 http_status 与
            # 非空中文 reason），不影响其余项；成功项首次 201，重放/更早
            # 日 200，严格更新 200 并记审计。显式空 X-Tenant-ID 在此之前
            # 由路由统一判 400；本地（本租户）凭证状态始终不变。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_json(
                    200,
                    {"results": [],
                     "reason": "请求不合法: 请求体缺失或长度声明非法"},
                )
                return
            except Exception:  # noqa: BLE001
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
                )
                return
            if not raw:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体缺失"}
                )
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_json(
                    200,
                    {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
                )
                return
            except json.JSONDecodeError:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
                )
                return

            try:
                ok, reason, results = store.sync_credential_status_batch(
                    tenant, data
                )
            except Exception:  # noqa: BLE001 批量同步失败绝不暴露内部细节
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 同步过程发生内部错误"}
                )
                return
            if not ok:
                self._send_json(
                    200, {"results": [], "reason": reason or "请求不合法"}
                )
                return
            self._send_json(200, {"results": results})

        def _get_trust_credential_status(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}?issuer_did=...：issuer_did 须唯一
            # 且非空，否则 400；未同步（含他租户双键）404，跨租户不可
            # 探测。已同步仅返回 status、reason、updated_at。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_synced_credential_status(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                },
            )

        def _get_trust_imported_credential(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET /v1/trust/credentials/imported/{credential_id}
            # ?issuer_did=...：issuer_did 须唯一且非空，缺失/重复/空值
            # 一律 400；未导入、跨租户或 issuer_did 不匹配（含他租户
            # 双键）404，存在性不可探测。成功 200 返回键序
            # issuer_did,credential_id,body,signature。纯只读，不写状态、
            # 不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_imported_credential(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "issuer_did": record.issuer_did,
                    "credential_id": record.credential_id,
                    "body": record.body,
                    "signature": record.signature,
                },
            )

        def _get_trust_credential_status_history(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}/history?issuer_did=...&limit=&after=
            # issuer_did 须唯一且非空，否则 400；limit 缺省 50，须为
            # 1..200 的 ASCII 十进制整数；after 缺省 0，须为非负 ASCII
            # 十进制整数；重复/非法一律 400。未同步双键（含他租户）404。
            # 只读：不写任何状态、不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)

            issuer_values = params.get("issuer_did")
            if issuer_values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(issuer_values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = issuer_values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )

            limit_values = params.get("limit")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError(
                        "查询参数 limit 须在 1 到 200 之间"
                    )
            else:
                limit = 50

            after_values = params.get("after")
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_synced_credential_status_history(
                tenant, issuer_did, credential_id, after, limit
            )
            self._send_json(
                200,
                {
                    "issuer_did": issuer_did,
                    "credential_id": credential_id,
                    "events": [
                        {
                            "status": event.status,
                            "reason": event.reason,
                            "updated_at": event.updated_at,
                            "issuer_key_version": event.issuer_key_version,
                            "audit_seq": event.audit_seq,
                            "audit_timestamp": event.audit_timestamp,
                            "cursor": event.cursor,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

        def _get_audit(self, tenant: str, query: str) -> None:            # GET /v1/audit?limit=&after=：租户内按 seq 升序。
            # limit 缺省 50，须为 1..200 的整数；after 缺省 0，须为
            # 非负整数；非法一律 400。返回 events 与 next_after，
            # 空页 next_after 保持 after。
            params = parse_qs(query, keep_blank_values=True)
            limit_values = params.get("limit")
            after_values = params.get("after")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError("查询参数 limit 须在 1 到 200 之间")
            else:
                limit = 50
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_audit(tenant, after, limit)
            self._send_json(
                200,
                {
                    "events": [
                        {
                            "seq": event.seq,
                            "timestamp": event.timestamp,
                            "tenant_id": event.tenant_id,
                            "action": event.action,
                            "resource_type": event.resource_type,
                            "resource_id": event.resource_id,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

    return Handler


def run(
    host: str = "127.0.0.1",
    port: int = 8080,
    store_path: Optional[str] = None,
    quiet: bool = False,
) -> None:
    """启动 HTTP 服务（阻塞）。"""
    store = VCStore(store_path)
    handler = build_handler(store)
    if quiet:
        handler.log_message = lambda *args, **kwargs: None  # noqa: E731
    httpd = ThreadingHTTPServer((host, port), handler)
    print(f"可验证凭证后端已启动: http://{host}:{port}")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()

    """分配租户内下一个持久化凭证状态历史游标（正整数，递增）。"""
    cursor = (
        self._local_credential_status_history_cursors.get(tenant_id, 0)
        + 1
    )
    self._local_credential_status_history_cursors[tenant_id] = cursor
    return cursor

def _backfill_local_credential_status_history_locked(self) -> None:
    """加载迁移：为有状态但无历史的本地凭证补一条兼容项（内存态）。

    对每个租户内已有状态行（status 为 active/revoked）、但该凭证
    没有任何状态历史项的旧状态，按 (租户, credential_id) 的稳定顺序
    补录一条内容取自状态行的兼容事件：active 事件 reason/revoked_at
    为 None；revoked 事件保存裁剪 reason 与 revoked_at；cursor 为该
    租户内新分配的持久化正整数，audit_seq/audit_timestamp 均为 None
    （无法追溯原始审计事件）。

    仅在内存中补录：兼容项随下一次任意原子写一并落盘；若此后无写
    操作则重启时按相同顺序重建，cursor 稳定。
    """
    for tenant_id in sorted(self._tenants):
        bucket = self._tenants[tenant_id]
        history = bucket.setdefault(
            "local_credential_status_history", {}
        )
        for credential_id in sorted(bucket.get("credentials", {})):
            rec = bucket["credentials"][credential_id]
            status = rec.get("status")
            if status not in ("active", "revoked"):
                continue
            entries = history.setdefault(credential_id, [])
            if entries:
                continue
            if status == "revoked":
                reason = rec.get("revoke_reason")
                revoked_at = rec.get("revoked_at")
            else:
                reason = None
                revoked_at = None
            entries.append(
                {
                    "status": status,
                    "reason": reason,
                    "updated_at": rec.get("status_updated_at"),
                    "revoked_at": revoked_at,
                    "cursor": (
                        self._next_local_credential_status_cursor_locked(
                            tenant_id
                        )
                    ),
                    "audit_seq": None,
                    "audit_timestamp": None,
                }
            )

@staticmethod
def _imported_credential_record(
    issuer_did: str, credential_id: str, row: Dict[str, Any]
) -> ImportedCredentialRecord:
    return ImportedCredentialRecord(
        issuer_did=issuer_did,
        credential_id=credential_id,
        body=row["body"],
        signature=row["signature"],
    )

@staticmethod
def _credential_body_field_error(
    body: Any,
) -> Tuple[Optional[str], int]:
    """校验外部凭证 body 字段，返回 (中文错误原因, 锚点版本)。

    规则与 :meth:`verify_trust_credential` 的凭证字段部分完全一致：
    body 须含 credential_id/issuer_did/subject_did/issued_at 非空
    字符串、claims 对象；issuer_key_version 可省略（按版本 1），
    提供时须为非布尔正整数。通过时错误原因为 None。
    """
    if not isinstance(body, dict):
        return "字段 body 必须为 JSON 对象", 1
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return f"凭证缺少字段: {field}", 1
        value = body[field]
        if not isinstance(value, str) or not value:
            return f"凭证字段 {field} 必须为非空字符串", 1
    if "claims" not in body:
        return "凭证缺少字段: claims", 1
    if not isinstance(body["claims"], dict):
        return "凭证字段 claims 必须为 JSON 对象", 1
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return "凭证字段 issuer_key_version 必须为正整数", 1
        key_version = version_obj
    return None, key_version

def import_trust_credential(
    self,
    tenant_id: str,
    data: Any,
) -> Dict[str, Any]:
    """导入一条外部凭证，返回结果字典。

    请求结构与凭证字段规则同 :meth:`verify_trust_credential`，但错误
    分类不同：
      - 请求/字段非法（非对象、字段缺失或多余、body 非对象、signature
        非空字符串、凭证必含字段缺失或类型错误、issuer_key_version
        非法）一律抛 ValidationError（HTTP 400）；
      - 锚点缺失/非 active、锚点公钥不可用、签名格式错误、密码学验签
        失败、凭证已过期均返回 ``{"valid": False, "reason": ...}``
        （非空中文原因），不写入、不记审计；
      - 验签通过后按 (tenant, issuer_did, credential_id) 持久化完整
        body 原文与 signature：首次导入 201 并记
        trust.credential.imported；相同内容重放 200、不替换、不重复
        审计；不同内容（body 或 signature 不一致）抛 ConflictError
        （HTTP 409），不写入。状态与审计同一次原子写，失败回滚。
    """
    # ---- 请求结构（错误 -> 400）----
    if not isinstance(data, dict):
        raise ValidationError("请求体必须为 JSON 对象")
    if set(data) != {"body", "signature"}:
        missing = [f for f in ("body", "signature") if f not in data]
        if missing:
            raise ValidationError(f"缺少字段: {', '.join(missing)}")
        extra = sorted(set(data) - {"body", "signature"})
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    body = data["body"]
    signature = data["signature"]
    if not isinstance(signature, str) or not signature:
        raise ValidationError("字段 signature 必须为非空字符串")

    # ---- 凭证字段（错误 -> 400）----
    field_error, key_version = self._credential_body_field_error(body)
    if field_error is not None:
        raise ValidationError(field_error)
    issuer_did = body["issuer_did"]
    credential_id = body["credential_id"]

    # ---- 锚点（缺失/非 active -> 200 valid:false，不写入）----
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None
            else None
        )
        anchor_row = (
            anchors.get(str(key_version))
            if anchors is not None
            else None
        )
        public_pem = (
            anchor_row.get("public_key", "")
            if anchor_row is not None
            else ""
        )
        anchor_status = (
            anchor_row.get("status", "active")
            if anchor_row is not None
            else None
        )
    if anchor_row is None:
        return {
            "valid": False,
            "reason": f"锚点不存在: {issuer_did}#{key_version}",
        }
    if anchor_status == "revoked":
        return {
            "valid": False,
            "reason": f"锚点已吊销: {issuer_did}#{key_version}",
        }
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return {
            "valid": False,
            "reason": (
                f"锚点公钥不可用: {issuer_did}#{key_version}"
                " 不是合法 P-256 公钥"
            ),
        }

    # ---- 签名（覆盖完整 body 的规范化 JSON）----
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return {
            "valid": False,
            "reason": "签名格式错误: 不是合法的 ES256 签名编码",
        }
    except crypto.InvalidSignature:
        return {
            "valid": False,
            "reason": "签名校验失败，凭证正文或签名可能被改动",
        }
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return {"valid": False, "reason": "签名校验失败: 验签过程发生内部错误"}

    # ---- 有效期（规则同 verify：仅 body 提供 expires_at 时检查）----
    if "expires_at" in body:
        expires_value = body["expires_at"]
        if (
            not isinstance(expires_value, str)
            or not _UTC_Z_SHAPE_RE.match(expires_value)
        ):
            return {
                "valid": False,
                "reason": (
                    "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                    "（YYYY-MM-DDTHH:MM:SSZ）"
                ),
            }
        try:
            expires_dt = _parse_utc_z(expires_value)
        except ValueError:
            return {
                "valid": False,
                "reason": (
                    "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                    "（YYYY-MM-DDTHH:MM:SSZ）"
                ),
            }
        if datetime.now(timezone.utc) >= expires_dt:
            return {"valid": False, "reason": CREDENTIAL_EXPIRED_REASON}

    # ---- 持久化（双键隔离、重放幂等、内容冲突、原子审计）----
    with self._lock:
        bucket = self._ensure_bucket_locked(tenant_id)
        issuer_map = bucket.setdefault(
            "imported_credentials", {}
        ).setdefault(issuer_did, {})
        existing = issuer_map.get(credential_id)
        if existing is not None:
            if (
                existing.get("body") == body
                and existing.get("signature") == signature
            ):
                # 相同内容重放：200、不替换、不重复审计
                return {
                    "valid": True,
                    "status_code": 200,
                    "record": self._imported_credential_record(
                        issuer_did, credential_id, existing
                    ),
                }
            # 不同内容：冲突，不写入、不记审计
            raise ConflictError(
                "外部凭证已导入且内容不同: "
                f"{issuer_did}#{credential_id}"
            )

        new_row = {"body": copy.deepcopy(body), "signature": signature}
        snapshot = self._snapshot_locked()
        try:
            issuer_map[credential_id] = new_row
            self._append_audit_locked(
                tenant_id,
                AUDIT_TRUST_CREDENTIAL_IMPORTED,
                "imported_credential",
                f"{issuer_did}#{credential_id}",
            )
            self._save_locked()
        except Exception:
            self._restore_locked(snapshot)
            raise
        return {
            "valid": True,
            "status_code": 201,
            "record": self._imported_credential_record(
                issuer_did, credential_id, new_row
            ),
        }

def get_imported_credential(
    self, tenant_id: str, issuer_did: str, credential_id: str
) -> ImportedCredentialRecord:
    """查询已导入的外部凭证原文与签名。

    按本租户 (issuer_did, credential_id) 双键查找；未导入、属他租户
    或 issuer_did 不匹配均抛 NotFoundError（HTTP 404，跨租户/存在性
    不可探测）。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = None
        if bucket is not None:
            row = (
                bucket.get("imported_credentials", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
        if row is None:
            raise NotFoundError(
                "外部凭证未导入: "
                f"{issuer_did}#{credential_id}"
            )
        return self._imported_credential_record(
            issuer_did, credential_id, row
        )

def sync_credential_status(
    self,
    tenant_id: str,
    data: Any,
) -> Dict[str, Any]:
    """同步一条外部凭证状态，返回结果字典。

    请求体须恰含 body（JSON 对象）与 signature（非空字符串）；

"""ES256 签名与规范化 JSON。

ES256 即 ECDSA over P-256 与 SHA-256。签名以 JWS 约定编码：
64 字节裸 R||S 的 base64url（无填充）。cryptography 库签出的是 DER，
这里在 DER 与 R||S 之间做转换。
"""

import base64
import json
from typing import Any, Dict

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import (
    decode_dss_signature,
    encode_dss_signature,
)

__all__ = [
    "InvalidSignature",
    "MalformedSignature",
    "canonicalize",
    "generate_private_key_pem",
    "public_key_pem_from_private",
    "validate_public_key_pem",
    "validate_signature_format",
    "sign",
    "verify",
]


class MalformedSignature(ValueError):
    """签名编码格式非法（无法解码或不是 64 字节裸 R||S）。"""


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode(text + padding)


def canonicalize(body: Dict[str, Any]) -> bytes:
    """正文按 key 升序的规范化 JSON 序列化（紧凑、UTF-8 字节）。"""
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def generate_private_key_pem() -> str:
    """生成 P-256 私钥，返回 PKCS8 PEM 字符串。"""
    private_key = ec.generate_private_key(ec.SECP256R1())
    pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return pem.decode("utf-8")


def public_key_pem_from_private(private_pem: str) -> str:
    """从私钥 PEM 导出对应的 SubjectPublicKeyInfo 公钥 PEM。"""
    private_key = serialization.load_pem_private_key(
        private_pem.encode("utf-8"), password=None
    )
    if not isinstance(private_key, ec.EllipticCurvePrivateKey):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    if not isinstance(private_key.curve, ec.SECP256R1):
        raise ValueError("私钥曲线不是 P-256")
    pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return pem.decode("utf-8")


def _load_public_key(public_pem: str) -> ec.EllipticCurvePublicKey:
    try:
        key = serialization.load_pem_public_key(public_pem.encode("utf-8"))
    except (ValueError, TypeError) as exc:
        raise ValueError(f"公钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePublicKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("公钥不是 P-256 椭圆曲线公钥")
    return key


def validate_public_key_pem(public_pem: str) -> None:
    """校验公钥 PEM 可解析且为 ES256 所需的 P-256 公钥，否则抛 ValueError。"""
    _load_public_key(public_pem)


def _load_private_key(private_pem: str) -> ec.EllipticCurvePrivateKey:
    try:
        key = serialization.load_pem_private_key(
            private_pem.encode("utf-8"), password=None
        )
    except (ValueError, TypeError) as exc:
        raise ValueError(f"私钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    return key


def sign(body: Dict[str, Any], private_pem: str) -> str:
    """对规范化正文做 ES256 签名，返回 base64url(R||S)。"""
    private_key = _load_private_key(private_pem)
    der = private_key.sign(
        canonicalize(body), ec.ECDSA(hashes.SHA256())
    )
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return _b64url(raw)


def validate_signature_format(signature_b64: str) -> None:
    """校验签名编码格式：须为可解码的 base64url 且裸 R||S 恰为 64 字节。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    try:
        raw = _b64url_decode(signature_b64)
    except Exception as exc:  # noqa: BLE001 解码异常（含 binascii）均属格式问题
        raise MalformedSignature("签名不是合法的 base64url 编码") from exc
    if len(raw) != 64:
        raise MalformedSignature("签名长度不是 64 字节，非合法 ES256 签名")


def verify(body: Dict[str, Any], signature_b64: str, public_pem: str) -> None:
    """校验签名：格式非法抛 MalformedSignature，验签失败抛 InvalidSignature。"""
    validate_signature_format(signature_b64)
    public_key = _load_public_key(public_pem)
    raw = _b64url_decode(signature_b64)
    r = int.from_bytes(raw[:32], "big")
    s = int.from_bytes(raw[32:], "big")
    der = encode_dss_signature(r, s)
    public_key.verify(der, canonicalize(body), ec.ECDSA(hashes.SHA256()))

try:
    crypto.validate_public_key_pem(public_pem)
except (ValueError, TypeError):
    return False, (
        "历史公钥不可用: 签发者 "
